SELECT DATE_TRUNC('WEEK', starts_on) AS week_start, PERCENTILE_APPROX(discount_pct, 0.9) AS discount_pct_p90, MIN(discount_pct) AS min_discount_pct, PERCENTILE_APPROX(discount_pct, 0.5) AS discount_pct_p50, COUNT(DISTINCT id) AS distinct_ids, MAX(discount_pct) FILTER (WHERE channel = 'partner') AS partner_max_discount_pct, COUNT(CASE WHEN channel = 'partner' THEN 1 END) AS partner_count FROM promotions GROUP BY week_start
